pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        c.seedMarket(1000);

        vm.deal(address(this), 1 ether);
        c.buyDrugs{value: 1 ether}();

        uint256 drugs = 500;
        uint256 refResult = c.calculateDrugSell(drugs);

        assertTrue(refResult > 0, "Reference calculateDrugSell should return > 0");
    }
}
